import React from "react";
import { NavLink } from "react-router-dom";
import Link from "@material-ui/core/Link";
import Avatar from "@material-ui/core/Avatar";
import { API_URL } from "../../config.js";
import classes from "./Header.module.css";

const Header = (props) => {
  const avatar = props.user.avatar ? `${API_URL + props.user.avatar}` : "";

  return (
    <header className={classes.App_header}>
      <div className={classes.brand}>
        <div className={classes.brandMark}>C</div>
        <div className={classes.brandText}>
          <div className={classes.brandName}>Circle</div>
          <div className={classes.brandTag}>твоя лента и круг людей</div>
        </div>
      </div>

      <div className={classes.loginBlock}>
        {props.isAuth ? (
          <div className={classes.userInfo}>
            <Avatar className={classes.userInfoItem} src={avatar}>
              {(props.login || "U").slice(0, 1).toUpperCase()}
            </Avatar>
            <span className={classes.userName}>{props.login}</span>
            <button className={classes.logoutBtn} onClick={props.logout} type="button">
              Выйти
            </button>
          </div>
        ) : (
          <div className={classes.loginBlock}>
            <NavLink to={"/register"} className={classes.loginLink}>
              <Link component="button" variant="body2" className={`${classes.authBtn} ${classes.ghostBtn}`}>
                Регистрация
              </Link>
            </NavLink>
            <NavLink to={"/login"} className={classes.loginLink}>
              <Link component="button" variant="body2" className={`${classes.authBtn} ${classes.primaryBtn}`}>
                Войти
              </Link>
            </NavLink>
          </div>
        )}
      </div>
    </header>
  );
};

export default Header;
